import Link from "next/link";
import { notFound } from "next/navigation";
import { prisma } from "@/core/server/prisma";

export default async function AdminOrderPage({ params }: { params: Promise<{ orderId: string }> }) { const order = await prisma.order.findUnique({ where: { id: (await params).orderId }, include: { user: { select: { email: true, name: true } }, items: { include: { productPrice: true } }, payments: { include: { events: true, refunds: true } }, entitlements: true, purchases: true } }); if (!order) notFound(); return <div><Link href="/admin/billing/orders" className="text-sm text-blue-700 underline">← Orders</Link><h1 className="mt-3 text-3xl font-bold">{order.number}</h1><p className="mt-2 text-slate-600">{order.user.name} · {order.user.email} · {order.status}</p><section className="mt-6 grid gap-4 md:grid-cols-2"><article className="rounded-xl border bg-white p-5"><h2 className="font-bold">Items</h2>{order.items.map((item) => <p key={item.id} className="mt-2 text-sm">{item.titleSnapshot} — {item.totalAmount / 100} {order.currency}</p>)}</article><article className="rounded-xl border bg-white p-5"><h2 className="font-bold">Entitlements</h2>{order.entitlements.length ? order.entitlements.map((item) => <p key={item.id} className="mt-2 text-sm">{item.type} · {item.status}</p>) : <p className="mt-2 text-sm text-slate-500">No granted rights yet.</p>}</article><article className="rounded-xl border bg-white p-5 md:col-span-2"><h2 className="font-bold">Payments and verified provider events</h2>{order.payments.map((payment) => <div key={payment.id} className="mt-3 border-t pt-3"><p className="text-sm">{payment.provider} · {payment.status} · {payment.amount / 100} {payment.currency}</p>{payment.events.map((event) => <p key={event.id} className="mt-1 text-xs text-slate-600">{event.eventType} · {event.processingStatus} · {event.providerEventId}</p>)}</div>)}</article></section></div>; }
